class NameStateWithPatternHashCodeTest {

    // Helper subclasses to provide deterministic, different hash codes for NameState instances
    static class NameStateHashA extends NameState {
        @Override
        public int hashCode() {
            return 101;
        }
    }

    static class NameStateHashB extends NameState {
        @Override
        public int hashCode() {
            return 202;
        }
    }

    @Test
    void testHashCode_sameNameStateAndPattern_areEqual() throws Exception {
        NameState ns = new NameStateHashA();

        // construct Patterns instance via reflection (constructor takes MatchType which we pass as null)
        Constructor<?> ctor = Patterns.class.getDeclaredConstructors()[0];
        ctor.setAccessible(true);
        Patterns pattern = (Patterns) ctor.newInstance(new Object[]{null});

        NameStateWithPattern a = new NameStateWithPattern(ns, pattern);
        NameStateWithPattern b = new NameStateWithPattern(ns, pattern);

        // direct invocation
        assertEquals(a.hashCode(), b.hashCode(), "hashCode should be equal for same nameState and pattern");

        // reflective invocation
        Method hashMethod = NameStateWithPattern.class.getMethod("hashCode");
        Object reflected = hashMethod.invoke(a);
        assertTrue(reflected instanceof Integer);
        assertEquals(a.hashCode(), ((Integer) reflected).intValue(), "reflective hashCode should match direct call");
    }

    @Test
    void testHashCode_nullPattern_sameNameState_areEqual() throws Exception {
        NameState ns = new NameStateHashA();

        NameStateWithPattern a = new NameStateWithPattern(ns, null);
        NameStateWithPattern b = new NameStateWithPattern(ns, null);

        assertEquals(a.hashCode(), b.hashCode(), "hashCode should be equal when pattern is null and nameState same");

        // reflective invocation as well
        Method hashMethod = NameStateWithPattern.class.getMethod("hashCode");
        int reflected = (Integer) hashMethod.invoke(b);
        assertEquals(b.hashCode(), reflected);
    }

    @Test
    void testHashCode_differentNameState_valuesDiffer() {
        NameState ns1 = new NameStateHashA();
        NameState ns2 = new NameStateHashB();

        NameStateWithPattern a = new NameStateWithPattern(ns1, null);
        NameStateWithPattern b = new NameStateWithPattern(ns2, null);

        // Given deterministic overridden hashCode implementations for the NameState subclasses,
        // the resulting combined hash should differ.
        assertNotEquals(a.hashCode(), b.hashCode(), "hashCode should differ for different nameState hashCodes");
